/// A fixed session start, sent on the wire as RFC3339 because that is what the
/// ingress parses. Pinning it rather than using "now" lets the dashboard
/// assertion below prove the exact instant survived the whole round trip.
const SESSION_STARTED_AT: &str = "2026-01-01T00:00:00Z";
const SESSION_STARTED_AT_SECONDS: i64 = 1_767_225_600;

/// A real `NodeSyncService` carrying a real `SupervisorStore`, on an ephemeral
/// loopback port. The server stops when this value is dropped.
struct TestServer {
    endpoint: String,
    _shutdown: oneshot::Sender<()>,
}

async fn start_sync_server(database_url: &str) -> TestServer {
    let ledger = LedgerStore::connect(database_url)
        .await
        .expect("the gated test database should accept ledger migrations");
    let pool = ackplane_server::db_pool::build_pool(
        database_url,
        ackplane_server::db_pool::TEST_POOL_MAX_SIZE,
    )
    .expect("the test database url should build a pool");
    let supervisors = SupervisorStore::connect(&pool)
        .await
        .expect("the gated test database should accept supervisor migrations");

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("the test service should bind loopback");
    let address = listener.local_addr().unwrap();
    let (shutdown_tx, shutdown_rx) = oneshot::channel();
    tokio::spawn(async move {
        Server::builder()
            .add_service(NodeSyncServiceServer::new(
                NodeSyncService::with_supervisor_store(
                    ledger,
                    supervisors,
                    v1::FlowControl {
                        max_in_flight_batches: 16,
                        max_batch_bytes: 1_048_576,
                    },
                ),
            ))
            .serve_with_incoming_shutdown(TcpListenerStream::new(listener), async {
                let _ = shutdown_rx.await;
            })
            .await
            .expect("the test service should run");
    });

    TestServer {
        endpoint: format!("http://{address}"),
        _shutdown: shutdown_tx,
    }
}

/// One genuinely enrolled node, plus the key material `enroll_repository`
/// derived for it, so a connection can authenticate for real rather than
/// being handed a pre-authorised stream.
struct EnrolledNode {
    tenant_id: String,
    repository_id: String,
    node_id: String,
    signing_key_id: String,
    seed: [u8; 32],
}

async fn enroll(database_url: &str) -> EnrolledNode {
    let unique = unique_id("slice2");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    let node_id = enroll_repository(database_url, &tenant_id, &repository_id, &unique).await;
    EnrolledNode {
        tenant_id,
        repository_id,
        node_id,
        signing_key_id: format!("signing-key-{unique}"),
        seed: Sha256::digest(format!("key-{unique}").as_bytes()).into(),
    }
}

async fn connect(server: &TestServer, node: &EnrolledNode) -> NodeSyncConnection {
    let signer = SeedSigner::new(
        node.signing_key_id.clone(),
        node.node_id.clone(),
        &node.seed,
    );
    NodeSyncConnection::open(
        &server.endpoint,
        &signer,
        &node.tenant_id,
        &node.repository_id,
        vec!["synchronize".to_string()],
        0,
    )
    .await
    .expect("an activated node should authenticate over real gRPC")
}

fn registration_frame(supervisor_id: &str, node_id: &str) -> v1::NodeFrame {
    v1::NodeFrame {
        frame: Some(v1::node_frame::Frame::SupervisorRegistration(
            v1::SupervisorRegistration {
                supervisor_id: supervisor_id.to_string(),
                node_id: node_id.to_string(),
                supervisor_version: "supervisor:v1".to_string(),
                protocol_version: "v1".to_string(),
                supported_directives: vec![v1::SupervisorDirectiveCapability::Notify as i32],
                supports_checkpoint: true,
                supports_force_termination: false,
                outbox_durability: v1::SupervisorOutboxDurability::Persistent as i32,
                recoverable_outbox: true,
            },
        )),
    }
}

fn session_frame(supervisor_id: &str, session_id: &str, worker_id: &str) -> v1::NodeFrame {
    v1::NodeFrame {
        frame: Some(v1::node_frame::Frame::SupervisorSession(
            v1::SupervisorSession {
                supervisor_id: supervisor_id.to_string(),
                session_id: session_id.to_string(),
                worker_id: worker_id.to_string(),
                runtime: v1::SupervisorRuntime::LocalMachine as i32,
                started_at: SESSION_STARTED_AT.to_string(),
                state: v1::SupervisorWorkerState::Started as i32,
            },
        )),
    }
}

fn heartbeat_frame(supervisor_id: &str) -> v1::NodeFrame {
    v1::NodeFrame {
        frame: Some(v1::node_frame::Frame::SupervisorHeartbeat(
            v1::SupervisorHeartbeat {
                supervisor_id: supervisor_id.to_string(),
            },
        )),
    }
}

async fn get_json(database_url: &str, tenant_id: &str, uri: String) -> Value {
    let pool = ackplane_server::db_pool::build_pool(
        database_url,
        ackplane_server::db_pool::TEST_POOL_MAX_SIZE,
    )
    .expect("the test database url should build a pool");
    let response = application(&pool, database_url, tenant_id)
        .await
        .oneshot(
            Request::builder()
                .uri(uri)
                .body(Body::empty())
                .expect("the dashboard request should build"),
        )
        .await
        .expect("the Bridge router should answer");
    body_json(response).await
}

#[tokio::test]
async fn a_supervisor_registers_sessions_and_heartbeats_over_one_live_connection() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let server = start_sync_server(&database_url).await;
    let node = enroll(&database_url).await;
    let mut connection = connect(&server, &node).await;

    let supervisor_id = unique_id("supervisor");
    let session_id = unique_id("session");
    let worker_id = unique_id("worker");

    let registered = connection
        .exchange_supervisor_frame(registration_frame(&supervisor_id, &node.node_id))
        .await
        .expect("a registration from the authenticated node should be accepted");
    assert_eq!(
        (
            registered.operation,
            registered.supervisor_id.as_str(),
            registered.idempotent_replay,
            registered.projection_advanced,
        ),
        (
            v1::SupervisorFrameOperation::Registration as i32,
            supervisor_id.as_str(),
            false,
            true,
        ),
        "the first registration is a genuine projection advance, not a replay"
    );

    let opened = connection
        .exchange_supervisor_frame(session_frame(&supervisor_id, &session_id, &worker_id))
        .await
        .expect("a session for a registered supervisor should be accepted");
    assert_eq!(
        (
            opened.operation,
            opened.supervisor_id.as_str(),
            opened.session_id.as_str(),
        ),
        (
            v1::SupervisorFrameOperation::Session as i32,
            supervisor_id.as_str(),
            session_id.as_str(),
        ),
        "the receipt names the session the frame opened"
    );

    let beat = connection
        .exchange_supervisor_frame(heartbeat_frame(&supervisor_id))
        .await
        .expect("a heartbeat for a registered supervisor should be accepted");
    assert_eq!(
        (beat.operation, beat.supervisor_id.as_str()),
        (
            v1::SupervisorFrameOperation::Heartbeat as i32,
            supervisor_id.as_str()
        ),
        "the heartbeat is acknowledged against the same supervisor"
    );

    // The read path: the dashboard must show what the connection just wrote.
    let inventory = get_json(
        &database_url,
        &node.tenant_id,
        format!("/api/v1/repositories/{}/supervisors", node.repository_id),
    )
    .await;
    let entry = inventory["entries"]
        .as_array()
        .expect("the inventory response carries an entries array")
        .iter()
        .find(|entry| entry["supervisor_id"] == supervisor_id.as_str())
        .expect("the registered supervisor should appear in the dashboard inventory");
    assert_eq!(
        (
            entry["node_id"].as_str(),
            entry["protocol_version"].as_str(),
            entry["supports_checkpoint"].as_bool(),
            entry["freshness"].as_str(),
        ),
        (
            Some(node.node_id.as_str()),
            Some("v1"),
            Some(true),
            Some("current"),
        ),
        "the dashboard reflects the registered capabilities and a heartbeat it has just seen"
    );
    assert!(
        entry["last_heartbeat_at_seconds"].is_i64(),
        "a supervisor that has heartbeated reports when, not null: {entry}"
    );

    let sessions = get_json(
        &database_url,
        &node.tenant_id,
        format!(
            "/api/v1/repositories/{}/supervisors/{supervisor_id}/sessions",
            node.repository_id
        ),
    )
    .await;
    let session = sessions["entries"]
        .as_array()
        .expect("the sessions response carries an entries array")
        .iter()
        .find(|entry| entry["session_id"] == session_id.as_str())
        .expect("the opened session should appear on the dashboard");
    assert_eq!(
        (
            session["worker_id"].as_str(),
            session["runtime"].as_str(),
            session["state"].as_str(),
            session["started_at_seconds"].as_i64(),
        ),
        (
            Some(worker_id.as_str()),
            Some("local_machine"),
            Some("started"),
            Some(SESSION_STARTED_AT_SECONDS),
        ),
        "the dashboard reflects the session exactly as the live frame declared it"
    );
}

#[tokio::test]
async fn an_identical_registration_on_a_fresh_connection_replays_rather_than_conflicting() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let server = start_sync_server(&database_url).await;
    let node = enroll(&database_url).await;
    let supervisor_id = unique_id("supervisor");

    let mut first = connect(&server, &node).await;
    let original = first
        .exchange_supervisor_frame(registration_frame(&supervisor_id, &node.node_id))
        .await
        .expect("the first registration should be accepted");
    assert!(
        !original.idempotent_replay,
        "the first registration is not a replay"
    );
    drop(first);

    // A genuinely new connection, as a restarted supervisor would open --
    // idempotency must be a property of the recorded fact, not of a live
    // stream that happens to remember what it already sent.
    let mut second = connect(&server, &node).await;
    let retried = second
        .exchange_supervisor_frame(registration_frame(&supervisor_id, &node.node_id))
        .await
        .expect("an identical registration must replay, never conflict");
    assert_eq!(
        (
            retried.idempotent_replay,
            retried.projection_advanced,
            retried.supervisor_id.as_str(),
        ),
        (true, false, supervisor_id.as_str()),
        "the retry replays the original projection without advancing it again"
    );
}

#[tokio::test]
async fn a_session_for_an_unregistered_supervisor_is_refused_as_a_typed_error() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let server = start_sync_server(&database_url).await;
    let node = enroll(&database_url).await;
    let mut connection = connect(&server, &node).await;

    let error = connection
        .exchange_supervisor_frame(session_frame(
            &unique_id("never-registered"),
            &unique_id("session"),
            &unique_id("worker"),
        ))
        .await
        .expect_err("a session naming an unregistered supervisor must be refused");

    match error {
        ClientError::FrameRefused {
            reason, retryable, ..
        } => assert_eq!(
            (reason, retryable),
            (RejectionReason::Unauthorized, false),
            "the client surfaces the server's own typed reason, not a bare stream failure"
        ),
        other => panic!("expected a typed FrameRefused, got {other:?}"),
    }

    // The refusal must not have poisoned the connection: registering properly
    // on the very same stream still works, which is the whole reason a frame
    // refusal is a different error from a connection refusal.
    let supervisor_id = unique_id("supervisor");
    let receipt = connection
        .exchange_supervisor_frame(registration_frame(&supervisor_id, &node.node_id))
        .await
        .expect("the connection survives a refused frame");
    assert!(
        receipt.projection_advanced,
        "the surviving connection can still advance the projection"
    );
}
